#include "ENGINE/Source/Anim/worldmatrix.h"
#include "ENGINE/Source/Tempest/c4quaternion.h"
#include <stdexcept>
#include <vector>
namespace{std::vector<NTempest::C34Matrix>s_stack(1);}
void WorldMatrixPush(){s_stack.push_back(s_stack.back());}void WorldMatrixPop(){if(s_stack.size()<=1)throw std::underflow_error("world matrix stack");s_stack.pop_back();}void WorldMatrixMult(const NTempest::C34Matrix&m){s_stack.back()*=m;}void WorldMatrixLoad(const NTempest::C34Matrix&m){s_stack.back()=m;}void WorldMatrixLoadIdentity(){s_stack.back()={};}void WorldMatrixTranslate(const NTempest::C3Vector&v){s_stack.back().Translate(v);}void WorldMatrixRotate(float a,const NTempest::C3Vector&v){WorldMatrixMult(NTempest::C34Matrix::Rotation(v,a,true));}void WorldMatrixRotate(const NTempest::C4Quaternion&q){s_stack.back().Rotate(q);}void WorldMatrixScale(float v){s_stack.back().Scale(v);}void WorldMatrixScale(const NTempest::C3Vector&v){s_stack.back().Scale(v);}void WorldMatrixBasis(const NTempest::C3Vector&x,const NTempest::C3Vector&y,const NTempest::C3Vector&z,const NTempest::C3Vector&p){auto&m=s_stack.back();m.a0=x.x;m.a1=x.y;m.a2=x.z;m.b0=y.x;m.b1=y.y;m.b2=y.z;m.c0=z.x;m.c1=z.y;m.c2=z.z;m.d0=p.x;m.d1=p.y;m.d2=p.z;}void WorldMatrixRemove(){WorldMatrixLoadIdentity();}const NTempest::C34Matrix&WorldMatrixGet(){return s_stack.back();}NTempest::C3Vector WorldMatrixTransform(const NTempest::C3Vector&v){return s_stack.back()*v;}NTempest::C3Vector WorldMatrixGetRow(unsigned r){if(r>3)throw std::out_of_range("matrix row");const float*d=s_stack.back().Data()+r*3;return{d[0],d[1],d[2]};}void WorldMatrixSetRow(unsigned r,const NTempest::C3Vector&v){if(r>3)throw std::out_of_range("matrix row");float*d=s_stack.back().Data()+r*3;d[0]=v.x;d[1]=v.y;d[2]=v.z;}
